import {SPECIES} from './world.js';
import {lineById,lineStats,generationLabel,lineageText,breedingKind} from './lines.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sex=s=>s==='male'?'♂ 수컷':'♀ 암컷';
export function lineBadge(state,b){
 if(!b?.lineage)return '<span class="line-unassigned">라인 미지정</span>';
 return `<span class="line-badge" title="${breedingKind(b.lineage.kind)}">${esc(lineageText(state,b))}${['cross','outcross'].includes(b.lineage.kind)?'<small>교배 이력</small>':''}</span>`;
}
export function lineBreedingPanel(state,m,f,ui,btn){
 const lineIds=[...new Set([m?.lineage?.lineId,f?.lineage?.lineId].filter(Boolean))];
 let next='라인을 지정하면 후손도 라인명과 누대를 달고 나옵니다.';
 if(m&&f&&lineIds.length===1){const g=Math.max(...[m,f].filter(b=>b.lineage?.lineId===lineIds[0]).map(b=>b.lineage.generation))+1;next=`${esc(lineById(state,lineIds[0]).name)} · ${generationLabel(g)}${m.lineage&&f.lineage?' · 라인 내 교배':' · 외부 개체 교배'}`;}
 return `<div class="line-breeding"><strong>후손 라인</strong>${lineIds.length===2?`<label class="field-label" for="brood-line">두 라인의 교배 · 후손을 기록할 라인</label><select class="field" id="brood-line"><option value="">라인 선택</option>${lineIds.map(id=>`<option value="${esc(id)}" ${ui.broodLineId===id?'selected':''}>${esc(lineById(state,id).name)} · ${generationLabel([m,f].find(b=>b.lineage?.lineId===id).lineage.generation+1)}</option>`).join('')}</select><p>두 부모의 출신 라인은 교배 기록에 함께 남습니다.</p>`:`<p>${next}</p>`}${m&&f?btn('이 종충 쌍으로 새 라인','line-new-pair','quiet'):''}<small>P = 종충 · F1부터 후손 · 부모 중 높은 누대에서 +1</small></div>`;
}
export function lineFormBody(state,draft,{art,traitBadges}){
 const species=Object.hasOwn(SPECIES,draft.species)?draft.species:'king',males=state.bugs.filter(b=>b.species===species&&b.sex==='male'),females=state.bugs.filter(b=>b.species===species&&b.sex==='female');
 if(!males.some(b=>b.id===draft.maleId))draft.maleId=males[0]?.id||'';
 if(!females.some(b=>b.id===draft.femaleId))draft.femaleId=females[0]?.id||'';
 const select=(list,id,chosen,label)=>`<label class="field-label" for="${id}">${label}</label><select class="field" name="${id}" id="${id}">${list.map(b=>`<option value="${esc(b.id)}" ${b.id===chosen?'selected':''}>${esc(b.name)} · ${b.length.toFixed(1)} mm · ${esc(lineageText(state,b))}</option>`).join('')||'<option value="">해당 성별 개체 없음</option>'}</select>`;
 const parent=b=>b?`<div class="parent">${art(b)}<strong>${esc(b.name)}</strong><small>${sex(b.sex)} · ${b.length.toFixed(1)} mm</small>${traitBadges(b)}${lineBadge(state,b)}</div>`:'<div class="parent">종충 없음</div>';
 return `<form id="line-form"><label class="field-label" for="line-name">라인 이름</label><input class="field" id="line-name" name="name" maxlength="24" value="${esc(draft.name)}" placeholder="내가 정한 라인 이름" required autocomplete="off"><label class="field-label" for="line-form-species">종</label><select class="field" id="line-form-species" name="species">${Object.entries(SPECIES).map(([id,s])=>`<option value="${id}" ${id===species?'selected':''}>${s.name}</option>`).join('')}</select><div class="line-form-selects">${select(males,'line-male',draft.maleId,'종충 수컷')}${select(females,'line-female',draft.femaleId,'종충 암컷')}</div><div class="pair">${parent(males.find(b=>b.id===draft.maleId))}<span class="pair-symbol">×</span>${parent(females.find(b=>b.id===draft.femaleId))}</div><p class="line-form-note">선택한 종충은 새 라인의 P가 됩니다. 확인 가능한 기존 후손과 번식통도 연결하며, 이미 다른 라인을 가진 후손의 지정은 유지합니다. 종충의 이전 라인 기록도 남습니다.</p><div class="modal-buttons"><button type="button" class="btn quiet" data-action="close">취소</button><button class="btn primary" type="submit" ${!males.length||!females.length?'disabled':''}>라인 만들기</button></div></form>`;
}
export function linesScreen(state,ui,{art,traitBadges,btn}){
 const lines=(state.lines||[]).filter(l=>(ui.lineSpecies==='all'||l.species===ui.lineSpecies)&&(ui.lineStatus==='all'||l.archived===(ui.lineStatus==='archived'))).slice().reverse();
 if(!lines.some(l=>l.id===ui.selectedLine))ui.selectedLine=lines[0]?.id||'';
 const line=lineById(state,ui.selectedLine),stats=line?lineStats(state,line):null;
 const generations=stats?[...new Set(stats.members.map(b=>b.lineage.generation))].sort((a,b)=>a-b):[];
 if(ui.lineGeneration!=='all'&&!generations.includes(Number(ui.lineGeneration)))ui.lineGeneration='all';
 const members=stats?stats.members.filter(b=>ui.lineGeneration==='all'||b.lineage.generation===Number(ui.lineGeneration)).sort((a,b)=>b.lineage.generation-a.lineage.generation||b.length-a.length):[];
 const parent=p=>`<div class="pedigree-parent"><strong>${esc(p.name)}</strong><span>${sex(p.sex)} · ${p.length.toFixed(1)} mm</span>${lineBadge(state,p)}</div>`;
 return `<div class="screen-heading"><div><h2>라인 관리</h2><p>종충에서 후손까지 누대 기록</p></div>${btn('새 라인 만들기','line-new','primary')}</div><div class="line-filters"><label>종<select class="field" id="line-species">${[['all','전체'],...Object.entries(SPECIES).map(([id,s])=>[id,s.name])].map(([id,name])=>`<option value="${id}" ${ui.lineSpecies===id?'selected':''}>${name}</option>`).join('')}</select></label><label>목록<select class="field" id="line-status">${[['active','관리 중'],['archived','보관한 라인'],['all','모든 라인']].map(([id,name])=>`<option value="${id}" ${ui.lineStatus===id?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="lines-layout"><aside class="line-list">${lines.map(l=>{const s=lineStats(state,l);return `<button class="line-list-card ${l.id===line?.id?'selected':''}" data-action="line-select" data-id="${esc(l.id)}" aria-pressed="${l.id===line?.id}"><strong>${esc(l.name)}</strong><span>${SPECIES[l.species].name}${l.archived?' · 보관 중':''}</span><b>${generationLabel(s.maxGeneration)} <small>사육 ${s.living} · 번식통 ${s.broods}</small></b></button>`;}).join('')||'<div class="empty">표시할 라인이 없어요.<br>종충 암수 한 쌍으로 첫 라인을 만들어 보세요.</div>'}</aside><section class="line-detail">${line?`<section class="panel"><div class="panel-head"><div><h3>${esc(line.name)}</h3><p>${SPECIES[line.species].name} · ${line.created}일째 지정</p></div><span class="pill">최고 ${generationLabel(stats.maxGeneration)}</span></div><div class="line-detail-body"><div class="line-actions">${btn('이 라인으로 번식','line-breed','primary',`data-id="${esc(line.id)}" ${!stats.males||!stats.females?'disabled':''}`)}${btn('이름 변경','line-rename','',`data-id="${esc(line.id)}"`)}${btn(line.archived?'관리 목록으로 복귀':'라인 보관','line-archive','quiet',`data-id="${esc(line.id)}"`)}</div><div class="line-stats"><div><strong>${stats.living}</strong><span>사육 중</span></div><div><strong>${stats.males} / ${stats.females}</strong><span>수컷 / 암컷</span></div><div><strong>${stats.offspring}</strong><span>누적 후손</span></div><div><strong>${stats.broods}</strong><span>번식통</span></div></div><h4>종충 · P</h4><div class="line-founders">${line.founders.map(p=>`<div class="line-founder">${art(p)}<div><strong>${esc(p.name)}</strong><p>${sex(p.sex)} · ${p.length.toFixed(1)} mm</p>${traitBadges(p)}${p.originLineage?`<small>출신 ${esc(lineageText(state,{lineage:p.originLineage}))}</small>`:'<small>첫 종충</small>'}</div></div>`).join('')}</div><div class="line-generation-head"><h4>누대별 개체</h4><label>누대<select id="line-generation" class="field"><option value="all">전체</option>${generations.map(g=>`<option value="${g}" ${Number(ui.lineGeneration)===g&&ui.lineGeneration!=='all'?'selected':''}>${generationLabel(g)}</option>`).join('')}</select></label></div><div class="line-member-grid">${members.map(b=>`<article class="line-member">${art(b)}<strong>${esc(b.name)}</strong><span>${sex(b.sex)} · ${b.length.toFixed(1)} mm</span>${lineBadge(state,b)}${traitBadges(b)}<small class="line-member-status">${b.status}</small>${b.alive?btn('사육실에서 보기','line-bug','',`data-id="${esc(b.id)}"`):''}</article>`).join('')||'<p class="empty">이 누대의 개체가 없어요.</p>'}</div><h4>교배·우화 기록</h4><div class="line-history">${line.records.slice().reverse().map(r=>`<details class="line-record"><summary><strong>${generationLabel(r.lineage.generation)}</strong> ${breedingKind(r.lineage.kind)}<span>${r.started===null?'기존 후손':`${r.started}일째 산란`} · ${r.sale?'유충 3마리 낙찰':r.emerged===null?(state.auctions||[]).some(a=>a.status==='active'&&a.kind==='larva'&&a.asset.id===r.id)?'경매 출품 중':'성장 중':`${r.emerged}일째 우화`}</span></summary><div class="pedigree-pair">${r.parents.map(parent).join('<span class="pair-symbol">×</span>')}</div><div class="pedigree-offspring">${r.offspring.map(b=>`<span>${sex(b.sex)} · ${b.length.toFixed(1)} mm · ${generationLabel(b.lineage.generation)}</span>`).join('')||(r.sale?`<span>유충 3마리 · ${r.sale.amount} 잎사귀 낙찰</span>`:'<span>알 3개 · 우화 대기</span>')}</div></details>`).join('')||'<p class="line-empty-history">아직 산란 기록이 없어요. 종충을 번식시키면 F1 기록이 시작됩니다.</p>'}</div></div></section>`:'<div class="panel line-empty-detail"><h3>라인을 선택해 주세요</h3><p>종충, 누대별 개체, 교배 이력과 성장 중인 번식통을 한곳에서 볼 수 있습니다.</p></div>'}</section></div>`;
}
